    # 排除 vision_model 前缀的 VIT 层，退回标准 TP 模式
    # vision_model 覆盖约 20+ VL 模型，并非所有 ViT 模型通用
    if module_name.startswith("vision_model"):
        return self._standard_linear_op(*args, **kwargs)

    if not self._use_flash_comm:
        return self._standard_linear_op(*args, **kwargs)

    if self._use_flash_comm_v2:
        return self._flash_comm_v2_op(module_name, *args, **kwargs)
    else:
        return self._flash_comm_v1_op(module_name, *args, **kwargs)

